import {
  BoxIcon,
  HomeIcon,
  ReceiptIcon,
  RouteIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import {
  Timeline,
  TimelineContent,
  TimelineHeader,
  TimelineIndicator,
  TimelineItem,
  TimelineSeparator,
  TimelineTitle,
} from '@/registry/ndeko/ui/timeline';

import { AgoTime } from './_parts/ago-time';
import { MARKER, MARKER_RAIL, MARKER_ROW } from './_parts/markers';
import { currentStepOf, stepStateOf, StepStateNote } from './_parts/step-state';

type OrderEvent = {
  title: string;
  detail: string;
  icon: Icon;
  at?: string;
};

const ORDER: OrderEvent[] = [
  {
    title: 'Order placed',
    detail:
      'Order OF-20931: two bags of oat granola and a tin of cocoa, 31.50 EUR.',
    icon: ReceiptIcon,
    at: '2026-11-11T13:00:00',
  },
  {
    title: 'Packed',
    detail: 'Packed in the Oatfield kitchen and sealed in a paper box.',
    icon: BoxIcon,
    at: '2026-11-11T19:00:00',
  },
  {
    title: 'Out for delivery',
    detail: 'On the van since this afternoon, eleven stops before yours.',
    icon: RouteIcon,
    at: '2026-11-12T14:10:00',
  },
  {
    title: 'Delivered',
    detail:
      'Expected today between 15:30 and 17:30, left with a neighbour if nobody is in.',
    icon: HomeIcon,
  },
];

const DONE_COUNT = 3;

const ICON_TILE = [
  MARKER,
  'bg-foreground/[0.06] text-muted-foreground scale-90 border-none',
  'group-data-completed/timeline-item:bg-primary group-data-completed/timeline-item:text-primary-foreground group-data-completed/timeline-item:scale-100',
].join(' ');

export default function Timeline06() {
  return (
    <Timeline
      defaultValue={DONE_COUNT}
      role='list'
      aria-label='Oatfield order OF-20931'
      className='[--marker:1.5rem]'
    >
      {ORDER.map((orderEvent, index) => {
        const step = index + 1;
        const state = stepStateOf(step, DONE_COUNT);

        return (
          <TimelineItem
            key={orderEvent.title}
            step={step}
            role='listitem'
            aria-current={currentStepOf(state)}
            className={MARKER_ROW}
          >
            <TimelineHeader>
              <TimelineIndicator className={ICON_TILE}>
                <orderEvent.icon className='size-3.5' />
              </TimelineIndicator>
              <TimelineSeparator className={MARKER_RAIL} />
              <TimelineTitle className='mt-0.5'>
                {orderEvent.title}
                <StepStateNote state={state} />
              </TimelineTitle>
            </TimelineHeader>
            <TimelineContent>
              {orderEvent.detail}
              {orderEvent.at && <AgoTime at={orderEvent.at} className='mt-2' />}
            </TimelineContent>
          </TimelineItem>
        );
      })}
    </Timeline>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';
import { TimelineDate } from '@/registry/ndeko/ui/timeline';

import { agoLabelOf, stampLabelOf } from './dates';

type AgoTimeProps = {
  at: string;
  className?: string;
};

export function AgoTime({ at, className }: AgoTimeProps) {
  return (
    <TimelineDate
      dateTime={at}
      title={stampLabelOf(at)}
      className={cn('mb-0', className)}
    >
      {agoLabelOf(at)}
    </TimelineDate>
  );
}

import { differenceInMinutes, format, parseISO } from 'date-fns';

/* Every time is read against one fixed moment and written without a time zone, so the server and the browser print the same labels. */
const NOW = '2026-11-12T15:00:00';

const MINUTES_PER_HOUR = 60;

const MINUTES_PER_DAY = 1440;

export function dayLabelOf(isoDay: string) {
  const day = parseISO(isoDay);
  return format(day, 'MMM d, yyyy');
}

export function stampLabelOf(isoTime: string) {
  const time = parseISO(isoTime);
  return format(time, "MMMM d, yyyy 'at' HH:mm");
}

function agoOf(count: number, unit: string) {
  if (count === 1) {
    return `1 ${unit} ago`;
  }
  return `${count} ${unit}s ago`;
}

export function agoLabelOf(isoTime: string) {
  const now = parseISO(NOW);
  const time = parseISO(isoTime);
  const minutes = differenceInMinutes(now, time);
  if (minutes < 1) {
    return 'Just now';
  }
  if (minutes < MINUTES_PER_HOUR) {
    return agoOf(minutes, 'minute');
  }
  if (minutes < MINUTES_PER_DAY) {
    const hours = Math.floor(minutes / MINUTES_PER_HOUR);
    return agoOf(hours, 'hour');
  }
  const days = Math.floor(minutes / MINUTES_PER_DAY);
  return agoOf(days, 'day');
}

/*
 * A marker wider than the 16px dot. Its size is --marker, set on the timeline: the row, the marker
 * and the rail are all placed from it, so the marker keeps its left edge on the edge of the piece.
 */
export const MARKER_ROW =
  'group-data-[orientation=vertical]/timeline:ms-[calc(var(--marker)_+_1rem)]';

export const MARKER = [
  'flex size-(--marker) items-center justify-center',
  'group-data-[orientation=vertical]/timeline:-left-[calc(var(--marker)/2_+_1rem)]',
].join(' ');

export const MARKER_RAIL = [
  'group-data-[orientation=vertical]/timeline:-left-[calc(var(--marker)/2_+_1rem)]',
  'group-data-[orientation=vertical]/timeline:h-[calc(100%_-_var(--marker)_-_0.25rem)]',
  'group-data-[orientation=vertical]/timeline:translate-y-[calc(var(--marker)_+_0.125rem)]',
].join(' ');

type StepState = 'done' | 'current' | 'ahead';

const STATE_WORD: Record<StepState, string> = {
  done: 'done',
  current: 'in progress',
  ahead: 'to come',
};

export function stepStateOf(step: number, doneCount: number): StepState {
  if (step <= doneCount) {
    return 'done';
  }
  if (step === doneCount + 1) {
    return 'current';
  }
  return 'ahead';
}

export function currentStepOf(state: StepState) {
  if (state === 'current') {
    return 'step' as const;
  }
  return undefined;
}

type StepStateNoteProps = {
  state: StepState;
};

/* The colour of the marker says where a step stands: this says it in words for a screen reader. */
export function StepStateNote({ state }: StepStateNoteProps) {
  return <span className='sr-only'>, {STATE_WORD[state]}</span>;
}
